import React from 'react';
import { motion } from 'framer-motion';

const FeatureImportance = ({ features }) => {
  if (!features?.length) return null;
  const maxAbs = Math.max(...features.map(f => Math.abs(f.impact)), 1e-9);

  return (
    <motion.div
      className="card feature-importance-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.1 }}
    >
      <div className="card-title">
        <div className="card-ico ico-c">🔑</div>
        <span className="card-title-text">SHAP Feature Importance</span>
      </div>

      <div className="feature-list">
        {features.map((f, i) => {
          const isPos = f.impact >= 0;
          const pct   = (Math.abs(f.impact) / maxAbs) * 100;
          return (
            <motion.div
              key={f.name}
              className="feature-item-row"
              initial={{ opacity: 0, x: -16 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.15 + i * 0.07 }}
            >
              <div className="feature-header">
                <span className="feature-name">{i + 1}. {f.name}</span>
                <span className={`feature-impact ${isPos ? 'positive' : 'negative'}`}>
                  {isPos ? '↗ Bullish' : '↘ Bearish'}
                </span>
              </div>
              <div className="feature-bar">
                <motion.div
                  className={`feature-bar-fill ${isPos ? 'positive' : 'negative'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.25 + i * 0.07 }}
                />
              </div>
              <div className="feature-val" style={{ color: isPos ? 'var(--green)' : 'var(--red)' }}>
                {f.impact >= 0 ? '+' : ''}{f.impact.toFixed(5)}
              </div>
            </motion.div>
          );
        })}
      </div>

      <div className="tip-box">
        💡 Positive SHAP values push the prediction <strong style={{color:'var(--green)'}}>UP</strong>, negative push it <strong style={{color:'var(--red)'}}>DOWN</strong>. Magnitude = strength of influence.
      </div>
    </motion.div>
  );
};

export default FeatureImportance;
